.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #3f4147;
    background-color: #2f3136;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    background-color: #40444b;
    color: #dcddde;
    outline: none;
}

.message-input textarea::placeholder {
    color: #72767d;
}

.message-input textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.send-btn {
    align-self: flex-end;
    padding: 8px 20px;
    border: none;
    border-radius: 6px;
    background-color: #5865f2;
    color: #fff;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

