toolArgs.file_text:
.message-item {
    position: relative;
    padding: 8px 16px;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: rgba(0, 0, 0, 0.12);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.timestamp {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    color: #dcddde;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 12px;
    border: 1px solid #3f4147;
    background-color: rgba(88, 101, 242, 0.15);
    color: #dcddde;
    font-size: 0.82rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: rgba(88, 101, 242, 0.3);
    border-color: #5865f2;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 8px;
    border: none;
    border-radius: 4px;
    background: none;
    color: #00aff4;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 16px;
    display: flex;
    gap: 2px;
    padding: 2px 4px;
    border-radius: 6px;
    background-color: #2f3136;
    border: 1px solid #3f4147;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    z-index: 10;
}

.action-btn {
    padding: 4px 10px;
    border: none;
    border-radius: 4px;
    background: none;
    color: #b9bbbe;
    font-size: 0.78rem;
    cursor: pointer;
    white-space: nowrap;
    transition: background-color 0.1s, color 0.1s;
}

.action-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #dcddde;
