arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "" : "expanded")">
        <MessageArea CurrentChannel="CurrentChannel"
                     Messages="displayMessages"
                     ThreadReplyCounts="threadReplyCounts"
                     HasMoreMessages="hasMoreMessages"
                     IsLoadingMore="isLoadingMore"
                     OnLoadMore="LoadOlderMessages"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction" />
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 50;

    private List<Channel> channels = [];
    private List<Message> allMessages = [];
    private List<Message> displayMessages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private int? selectedChannelId;
    private bool hasMoreMessages;
    private bool isLoadingMore;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    private Channel? CurrentChannel =>
        channels.FirstOrDefault(c => c.Id == selectedChannelId);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();

        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        CloseThread();

        allMessages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        hasMoreMessages = allMessages.Count == PageSize;
        ComputeDisplayMessages();

        await ChatService.MarkChannelReadAsync(channelId);

        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0 && channels[idx].UnreadCount > 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannelId is null || isLoadingMore) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, allMessages.Count, PageSize);
        hasMoreMessages = older.Count == PageSize;

        allMessages.AddRange(older);
        ComputeDisplayMessages();
        isLoadingMore = false;
    }

    private void ComputeDisplayMessages()
    {
        // Show only root messages (not replies) in the main list
        var rootMessages = allMessages.Where(m => m.ReplyToId is null).ToList();

        // Compute reply counts from loaded messages
        threadReplyCounts = allMessages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        displayMessages = rootMessages;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;

        var message = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        allMessages.Insert(0, message);
        ComputeDisplayMessages();
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = allMessages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        var thread = await ChatService.GetThreadAsync(rootMessageId);
        threadMessages = thread.Where(m => m.Id != rootMessageId).ToList();
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannelId.Value, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update reply count in the main view
        if (!allMessages.Any(m => m.Id == reply.Id))
        {
            allMessages.Add(reply);
        }
        ComputeDisplayMessages();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh message reactions locally
        var idx = allMessages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = allMessages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                reactions[existing] = r with { Users = [.. r.Users, "You"] };
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            allMessages[idx] = msg with { Reactions = reactions };
            ComputeDisplayMessages();
        }
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    background-color: #36393f;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

